function whtUI(){var sel=49;
$("tc").innerHTML='<div class="two"><div class="c"><h3>Pakistan Withholding Tax Finder</h3><p>Type the payment, service or product, pick it from the list, and the section and rate are applied automatically (TY 2027 rates).</p><label>Payment / service / product type</label><input id="wq" placeholder="e.g. rent, IT services, import, dividend, property…" autocomplete="off"><div id="wl"></div><div class="fg"><div><label>Recipient</label><select id="wr"><option>Company</option><option>Individual & AOP</option></select></div><div><label>Taxpayer status</label><select id="ws"><option>Active (filer)</option><option>Not in ATL (non-filer)</option></select></div><div><label>Amount (PKR)</label><input id="wa" type="number" min="0" value="1000000"></div></div></div><div class="c"><h3>Result</h3><div class="tw"><table id="wo"></table></div><br><a class="btn" href="/contact/" style="color:#1b1500">Confirm with an adviser</a></div></div><div class="c" style="margin-top:18px"><h3>Full rate table: Company / Individual & AOP (Active / Non-active %)</h3><input id="wf" placeholder="Filter by section or keyword…"><div class="tw" style="max-height:440px;overflow:auto"><table id="wt" style="min-width:680px"></table></div><p class="note" style="color:var(--mute)">Rates follow the KPMG Taseer Hadi & Co. "Withholding Tax Collection / Deduction TY 2027" card (July 2026). Non-ATL persons pay 100% higher rates unless stated otherwise. Second/Tenth Schedule exemptions may apply; salary, electricity, vehicle-transfer and token-tax slabs are not covered here.</p></div>';
function calc(){var e=E[sel],o=wrate(e,$("wr").selectedIndex===0,$("ws").selectedIndex,+$("wa").value||0);
$("wo").innerHTML='<tr><th>Section</th><td>'+e[0]+'</td></tr><tr><th>Type</th><td>'+e[1]+'</td></tr>'+(o.msg?'<tr><th>Note</th><td>'+o.msg+'</td></tr>':'<tr><th>Rate applied</th><td>'+o.r+'</td></tr><tr><th>Tax to withhold</th><td class="big">'+m(o.t)+'</td></tr><tr><th>Net payable</th><td>'+m((+$("wa").value||0)-o.t)+'</td></tr>')+'<tr><th>Nature</th><td>'+e[4]+'</td></tr><tr><th>Deducted / collected by</th><td>'+e[5]+'</td></tr>'}
function list(){var q=$("wq").value.toLowerCase().split(" ").filter(Boolean),r=[];E.forEach(function(e,i){var l=wlab(e).toLowerCase();if(q.every(function(w){return l.indexOf(w)>-1}))r.push(i)});
$("wl").innerHTML=r.slice(0,8).map(function(i){return '<button class="lb" data-i="'+i+'"><b>'+E[i][0]+'</b> <small>'+E[i][1]+'</small></button>'}).join("")+(r.length>8?'<small style="color:var(--mute)">'+(r.length-8)+' more… keep typing</small>':"")||'<small style="color:var(--mute)">No match. Try another word.</small>';
document.querySelectorAll("#wl .lb").forEach(function(b){b.onclick=function(){sel=+b.dataset.i;$("wq").value=wlab(E[sel]);$("wl").innerHTML="";calc()}})}
function tbl(){var q=$("wf").value.toLowerCase();$("wt").innerHTML='<tr><th style="width:90px">Section</th><th style="width:auto">Description</th><th style="width:90px">Company</th><th style="width:100px">Ind & AOP</th></tr>'+E.filter(function(e){return wlab(e).toLowerCase().indexOf(q)>-1}).map(function(e){return '<tr><td>'+e[0]+'</td><td>'+e[1]+'</td><td>'+pr(e[2])+'</td><td>'+pr(e[3])+'</td></tr>'}).join("")}
$("wq").value=wlab(E[sel]);$("wq").oninput=list;$("wf").oninput=tbl;$("wr").onchange=$("ws").onchange=$("wa").oninput=calc;tbl();calc()}
