if(t.id==="wht"){whtUI();return}$("tc").innerHTML='<div class="two"><div class="c"><h3>'+t.n+'</h3><p>'+t.d+'</p><div class="fg">'+t.f.map(function(f){return '<div><label>'+f[1]+'</label>'+(Array.isArray(f[2])?'<select data-f="'+f[0]+'">'+f[2].map(function(o){return '<option>'+o+'</option>'}).join("")+'</select>':'<input data-f="'+f[0]+'" type="number" min="0" value="'+f[2]+'">')+'</div>'}).join("")+'</div></div><div class="c"'+(t.tb?' style="grid-column:1/-1"':'')+'><h3>Result '+(t.cur?"("+t.cur+")":"")+'</h3><div class="tw"><table id="rs"></table></div><br><a class="btn" href="/contact/" style="color:#1b1500">Talk to an adviser</a>'+(t.note?'<p class="note" style="color:var(--mute)">'+t.note+'</p>':t.id.indexOf("pk")==0&&t.id!=="gst"&&t.id!=="wht"?'<p class="note" style="color:var(--mute)">Salary-slab estimate on taxable salary income only. Surcharge on income above PKR 10m: 10% (FY25), 9% (FY26), none (FY27); not applied in FY23/FY24. Rebates, allowances, deductions and credits are not included.</p>':'')+'</div></div>';
function go(){var v={};document.querySelectorAll("#tc [data-f]").forEach(function(e){v[e.dataset.f]=e.tagName==="SELECT"?e.value:(+e.value||0)});
var R=t.c(v);$("rs").innerHTML=t.tb?R.map(function(r,i){var last=i===R.length-1;return '<tr>'+r.map(function(c,j){return i===0?'<th style="width:auto">'+c+'</th>':(j===0||last?'<th style="width:auto">'+c+'</th>':'<td>'+c+'</td>')}).join("")+'</tr>'}).join(""):R.map(function(r,i){return '<tr><th>'+r[0]+'</th><td'+(i===1?' class="big"':'')+'>'+r[1]+'</td></tr>'}).join("")}
