/* ===== FINANCIAL CALCULATORS ===== */
var FCUR="PKR",CURS=["PKR","AED","SAR","BHD","GBP","USD","EUR"];
function fx(x){return isFinite(x)?x.toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2}):"n/a"}
function cu(x){return FCUR+" "+fx(x)}
function fp(x){return isFinite(x)?x.toFixed(2)+"%":"n/a"}
function pmt(P,i,n){return n<=0?0:i===0?P/n:P*i/(1-Math.pow(1+i,-n))}
function nmo(v){return Math.max(0,Math.round(v.u==="Months"?v.t:v.t*12))}
function ym(k){if(!isFinite(k))return"never";var y=Math.floor(k/12),mo=k%12;return(y?y+" yr ":"")+(mo||!y?mo+" mo":"")}
function gtab(head,rows,h){return '<div class="c tw" style="margin-top:24px"><h3>'+h+'</h3><table style="min-width:520px"><tr>'+head.map(function(c){return '<th style="width:auto">'+c+'</th>'}).join("")+'</tr>'+rows.map(function(r){return '<tr>'+r.map(function(c){return '<td>'+c+'</td>'}).join("")+'</tr>'}).join("")+'</table></div>'}
function sched(P,i,n,pay){var b=P,rows=[],yi=0,yp=0;n=Math.min(n,1200);
 for(var k=1;k<=n;k++){var it=b*i,pr=Math.min(pay-it,b);b-=pr;yi+=it;yp+=pr;if(k%12===0||k===n||b<=.005){rows.push([Math.ceil(k/12),cu(yp),cu(yi),cu(Math.max(b,0))]);yi=0;yp=0;if(b<=.005)break}}
 return rows}
function lsch(P,i,pay,n,fl){if(!(P>0)||!(pay>0))return"";var cap=n>0?n:1200,b=P,k=0,m=[],tp=0,ti=0;
while(b>.005&&k<cap){var it=fl?fl.i:b*i,pr=fl?fl.p:Math.min(pay-it,b);if(!fl&&pay<=it+1e-9)return"";if(pr>b)pr=b;b-=pr;if(b<.005)b=0;k++;tp+=pr;ti+=it;m.push([k,pr+it,pr,it,b])}
if(!m.length)return"";var yr=[];m.forEach(function(r){var y=Math.ceil(r[0]/12),o=yr[y-1]||(yr[y-1]=[y,0,0,0,0]);o[1]+=r[1];o[2]+=r[2];o[3]+=r[3];o[4]=r[4]});
function tb(h,rows,mx){return '<div class="lsw-b"'+(mx?' style="max-height:420px;overflow:auto"':'')+'><table style="min-width:520px"><tr>'+h.map(function(c){return '<th style="width:auto">'+c+'</th>'}).join("")+'</tr>'+rows.map(function(r){return '<tr><td>'+r[0]+'</td>'+r.slice(1).map(function(c){return '<td>'+cu(c)+'</td>'}).join("")+'</tr>'}).join("")+'<tr><th>Total</th><th>'+cu(tp+ti)+'</th><th>'+cu(tp)+'</th><th>'+cu(ti)+'</th><th></th></tr></table></div>'}
return '<div class="c tw lsw" style="margin-top:24px"><div style="display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:10px;margin-bottom:10px"><h3 style="margin:0">Repayment schedule ('+k+' instalments)</h3><div class="tabs"><button class="on" data-lsw="m">Monthly</button><button data-lsw="y">Yearly</button></div></div><div data-lsv="m">'+tb(["Instalment no.","Payment","Principal","Interest","Balance"],m,1)+'</div><div data-lsv="y" hidden>'+tb(["Year","Payment","Principal","Interest","Balance"],yr)+'</div></div>'}
document.addEventListener("click",function(e){var b=e.target.closest&&e.target.closest("[data-lsw]");if(!b)return;var w=b.closest(".lsw");w.querySelectorAll("[data-lsw]").forEach(function(x){x.classList.toggle("on",x===b)});w.querySelectorAll("[data-lsv]").forEach(function(x){x.hidden=x.dataset.lsv!==b.dataset.lsw})});
function amort(P,i,n){return n>0&&P>0?gtab(["Year","Principal paid","Interest paid","Balance"],sched(P,i,n,pmt(P,i,n)),"Year-by-year schedule"):""}
function sim(P,i,pay){var b=P,ti=0,k=0;while(b>.005&&k<1200){var it=b*i;if(i>0&&pay<=it+1e-9)return{k:Infinity,ti:Infinity};var pr=Math.min(pay-it,b);b-=pr;ti+=it;k++}return{k:k,ti:ti}}
var CMP2={"Monthly":12,"Quarterly":4,"Semi-annually":2,"Annually":1,"Daily":365};
function grow(v){var n=Math.round(v.y*12),i=Math.pow(1+v.r/100/CMP2[v.cf],CMP2[v.cf]/12)-1,b=v.p,con=v.p,rows=[];
 for(var k=1;k<=n;k++){b=b*(1+i)+v.m;con+=v.m;if(k%12===0||k===n)rows.push([Math.ceil(k/12),cu(con),cu(b-con),cu(b)])}
 return{fv:b,con:con,rows:rows}}
function npvOf(r,inv,cf){var s=-inv;cf.forEach(function(c,t){s+=c/Math.pow(1+r,t+1)});return s}
function pcf(s){return String(s).split(/[,\s;]+/).filter(function(x){return x!==""}).map(Number).filter(function(x){return isFinite(x)})}
